export async function loadInfrastructureObservations(source,fetcher=globalThis.fetch){
 const path=source?.downloads?.observations||source?.observations_url;
 if(!path)return arr(source?.national);
 const key=absolute(path);
 return observationCache.getOrCreate(PROJECT+':observations:'+key,async()=>{
  try{
   const response=await fetcher(key);
   if(!response.ok)throw Error('HTTP '+response.status);
   const data=await response.json();
   if(data.project_id&&data.project_id!==PROJECT)throw Error('Неверный проект в файле наблюдений');
   if(String(data.source_id)!==sid(source))throw Error('Неверный источник в файле наблюдений');
   if(!Array.isArray(data.observations))throw Error('В файле отсутствует таблица наблюдений');
   return data.observations;
  }catch(e){throw new DataLoadError('Не удалось загрузить источник '+sid(source)+': '+e.message);}
 });
}


